import * as React from "react";
import { View, Text, StyleSheet } from "react-native";

export function ApplicationDeadline({ date }) {
  return (
    <View style={styles.deadlineContainer}>
      <Text style={styles.label}>SON BAŞVURU:</Text>
      <Text style={styles.date}>{date}</Text>
    </View>
  );
}

const styles = StyleSheet.create({
  deadlineContainer: {
    display: "flex",
    marginTop: 16,
    width: "100%",
    flexDirection: "row",
    alignItems: "center",
    gap: 4,
  },
  label: {
    color: "#878787",
    fontWeight: "400",
    fontSize: 16,
  },
  date: {
    color: "#1D1D1D",
    fontWeight: "500",
    fontSize: 16,
  },
});
